<?php
// 2.7.08 Trail Sights engine gaps, third pass A: buff2= (a second lucky moment: two buffs in one row), lair hints from real state (hint=snore|webhum|glow|rut:
// nights since this gnome last went into the lair ahead), hint=firstroom (the delve's first rooms) + the delve-start hook, nxt= effects on the next Trail stretch.
// php tests/trail_sights_280.php GAME_DIR   (an installed game, player "sprout"; walk.sh installs one). Model: tests/trail_sights_279.php.
$_SERVER['SCRIPT_NAME'] = '/adventure.php';
require $argv[1] . '/includes/bootstrap.php';
require_once $argv[1] . '/includes/adventure.php';
require_once $argv[1] . '/includes/trail_tiles.php';
require_once $argv[1] . '/includes/trail_sights.php';
require_once $argv[1] . '/includes/tools.php';
require_once $argv[1] . '/includes/stop_folk.php';
require_once $argv[1] . '/includes/landmarks.php';
require_once $argv[1] . '/includes/fresh_start.php';
require_once $argv[1] . '/includes/schema.php';
$fails = 0;
set_setting('npc_clockwork', '0'); set_setting('sights_walk_cap', '0');
$GLOBALS['gv_sights_nocache'] = true;
set_exception_handler(function (Throwable $e) { echo '  EXCEPTION ' . get_class($e) . ': ' . $e->getMessage() . ' @ ' . basename($e->getFile()) . ':' . $e->getLine() . "\n"; exit(1); });
function ok(string $what, bool $cond, string $extra = ''): void { global $fails; echo ($cond ? '  ok   ' : '  FAIL ') . $what . ($cond ? '' : "  $extra") . "\n"; if (!$cond) $fails++; }
$all = trail_sights_all(); $base = $all['grassland-the-clover-patch'];
$lint = fn(array $chg, string $word) => array_values(array_filter(trail_sight_lint($chg + $base), fn($p) => str_contains($p, $word)));
$u = q_one("SELECT * FROM users WHERE username = 'sprout'");
$uid = (int)$u['id'];
$row = fn() => q_one('SELECT * FROM users WHERE id = ?', [$uid]);
$clear = fn() => q('UPDATE users SET ev_stat = NULL, ev_amt = 0, ev_until = NULL, ev_day = NULL, ev_scope = NULL, ev2_stat = NULL, ev2_amt = 0, ev2_until = NULL, ev2_day = NULL, ev2_scope = NULL WHERE id = ?', [$uid]);

echo "== the schema: ev2_* columns (db_migrate list, idempotent, fresh start)\n";
$cols = array_map(fn($c) => $c[1], array_filter(schema_statements('sqlite')[2], fn($c) => $c[0] === 'users' && str_starts_with($c[1], 'ev2_')));
ok('schema.php lists the five ev2_* columns', array_values($cols) === ['ev2_stat', 'ev2_amt', 'ev2_until', 'ev2_day', 'ev2_scope'], json_encode($cols));
$r1 = db_migrate(db(), 'sqlite'); $r2 = db_migrate(db(), 'sqlite');
ok('db_migrate again adds nothing and fails nothing', !array_filter((array)$r2, fn($x) => is_string($x) && str_contains($x, 'ev2_')) && empty($GLOBALS['gv_migrate_errors']), json_encode($GLOBALS['gv_migrate_errors'] ?? null));
sights3a_ev2_columns(); ok('the safety net (sights3a_ev2_columns) is a no-op on an upgraded copy', array_key_exists('ev2_stat', $row()));
$fc = fresh_start_columns(); ok('fresh start empties the second slot', array_key_exists('ev2_stat', $fc) && $fc['ev2_amt'] === 0 && array_key_exists('ev2_scope', $fc));
$tmp = new PDO('sqlite::memory:'); $tmp->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION); $tmp->exec('CREATE TABLE users (id INTEGER PRIMARY KEY, ev_stat VARCHAR(10) NULL)'); $tmp->exec('INSERT INTO users (id) VALUES (1)');
foreach (SIGHTS3A_EV2_COLS as [$t, $c, $d]) $tmp->exec("ALTER TABLE $t ADD COLUMN $c $d");   // the same statement db_migrate runs: an old save keeps its row, the new columns get their defaults
$old = $tmp->query('SELECT * FROM users')->fetch(PDO::FETCH_ASSOC);
ok('an old save gains the columns with empty values', $old['ev2_stat'] === null && (int)$old['ev2_amt'] === 0 && $old['ev2_scope'] === null, json_encode($old));

echo "== buff2=: two lucky moments at once\n";
$clear(); $u0 = $row(); $g0 = eff_stat($u0, 'grit'); $l0 = eff_stat($u0, 'luck');
apply_event_effect($u0, 'buff:grit:1:60'); $res = apply_event_effect($row(), 'buff2:luck:2:60'); $u1 = $row();
ok('grit +1 (slot 1) and luck +2 (slot 2) together', eff_stat($u1, 'grit') === $g0 + 1 && eff_stat($u1, 'luck') === $l0 + 2, json_encode([$g0, $l0, eff_stat($u1, 'grit'), eff_stat($u1, 'luck')]));
ok('the line names the second boost', str_contains(implode(' ', $res), '+2 Luck for 60 minutes'), json_encode($res));
$fx = array_map(fn($e) => $e[1] . ': ' . $e[2], active_effects($u1));
ok('the effects list (Today, the status card) shows both', in_array('A lucky moment: Grit +1', $fx, true) && in_array('A second lucky moment: Luck +2', $fx, true), json_encode($fx));
apply_event_effect($u1, 'buff:sense:3:60'); $u2 = $row();
ok('a new buff= replaces slot 1 only; slot 2 stays', eff_stat($u2, 'grit') === $g0 && eff_stat($u2, 'luck') === $l0 + 2 && $u2['ev_stat'] === 'sense');
apply_event_effect($u2, 'buff2:all:1:60'); $u3 = $row();
ok('buff2=all: every stat +1 on top of slot 1', eff_stat($u3, 'luck') === $l0 + 1 && eff_stat($u3, 'sense') === eff_stat($u0, 'sense') + 4, json_encode([eff_stat($u3, 'luck'), eff_stat($u3, 'sense')]));
q('UPDATE users SET ev2_until = ? WHERE id = ?', [gmdate('Y-m-d H:i:s', time() - 5), $uid]); $u4 = $row();
ok('slot 2 expires by its own clock', eff_stat($u4, 'luck') === $l0 && !array_filter(active_effects($u4), fn($e) => $e[1] === 'A second lucky moment'));
set_setting('game_clock_on', '1'); setting('__reload__');
$clear(); q('UPDATE users SET game_day = 10 WHERE id = ?', [$uid]); $res = apply_event_effect($row(), 'buff2:nimble:1:sleep'); $u5 = $row();
ok('buff2=...:sleep lasts until the next sleep', (int)$u5['ev2_day'] === 10 && eff_stat($u5, 'nimble') === eff_stat($u0, 'nimble') + 1 && str_contains(implode(' ', $res), 'until you sleep'), json_encode([$u5['ev2_day'], $res]));
q('UPDATE users SET game_day = 11 WHERE id = ?', [$uid]); ok('... and is over once the game day moves on', eff_stat($row(), 'nimble') === eff_stat($u0, 'nimble'));
q('UPDATE users SET game_day = 10 WHERE id = ?', [$uid]);
$clear(); $vil = q_one("SELECT * FROM locations WHERE kind = 'village' ORDER BY id LIMIT 1");
$lines = trail_sight_pay($row(), ['name' => 'x'] + $vil, 'buff=grit:1:60,buff2=luck:2:60'); $u6 = $row();
ok('one Sight reward string with buff= and buff2= pays both', $u6['ev_stat'] === 'grit' && $u6['ev2_stat'] === 'luck' && count(array_filter($lines, fn($l) => str_contains($l, 'for 60 minutes'))) === 2, json_encode($lines));
$clear();
ok('lint: buff= + buff2= is clean', !$lint(['rewards' => 'buff=grit:1:60,buff2=luck:2:sleep'], 'buff'));
ok('lint: two plain buff= are refused (use buff2=)', (bool)$lint(['rewards' => 'buff=grit:1:60,buff=luck:2:60'], 'buff2='));
ok('lint: two buff= with conditions or chances are fine (alternatives)', !$lint(['rewards' => 'buff=grit:1:60?dp=dawn,buff=luck:2:60@30'], 'buff'));
ok('lint: a bad buff2= is refused', (bool)$lint(['rewards' => 'buff2=strength:1:60'], 'buff2=') && (bool)$lint(['rewards' => 'buff2=luck'], 'buff2='));

echo "== hint=snore|webhum|glow|rut: nights since the last lair run\n";
$lairLoc = q_one("SELECT l.* FROM locations l JOIN landmarks lm ON lm.location_id = l.id WHERE lm.kind = 'lair' ORDER BY l.id LIMIT 1");
$lairLm = landmark_at((int)$lairLoc['id']); $boss = lair_boss($lairLm);
q("UPDATE expeditions SET status = 'done' WHERE user_id = ?", [$uid]);
q("DELETE FROM landmark_uses WHERE user_id = ? AND landmark_id = ? AND action = 'lair'", [$uid, $lairLm['id']]);
$at = ['name' => 'a verb', 'region_id' => (int)$lairLoc['region_id'], 'kind' => 'village', 'id' => 0];
$h = trail_sight_hint($row(), $at, 'snore');
ok('never been in: "never", the lair\'s own creature named', str_contains($h, 'never gone in') && str_contains($h, (string)$boss['name']), $h);
$day4 = gmdate('Y-m-d', strtotime(landmark_day() . ' 00:00:00 UTC') - 4 * 86400);
db_insert('landmark_uses', ['user_id' => $uid, 'landmark_id' => (int)$lairLm['id'], 'action' => 'lair', 'day' => $day4, 'at' => now()]);
$h = trail_sight_hint($row(), $at, 'snore'); ok('4 nights since the last run: 4 snores, sound asleep', str_contains($h, 'Snores: 4.') && str_contains($h, '4 nights since you last went in') && str_contains($h, 'sound asleep'), $h);
ok('webhum: low and slow for a settled lair', str_contains(trail_sight_hint($row(), $at, 'webhum'), 'low and slow'));
db_insert('landmark_uses', ['user_id' => $uid, 'landmark_id' => (int)$lairLm['id'], 'action' => 'lair', 'day' => landmark_day(), 'at' => now()]);
ok('a run today: wide awake, the web high and twitchy, the rut fresh', str_contains(trail_sight_hint($row(), $at, 'snore'), 'wide awake') && str_contains(trail_sight_hint($row(), $at, 'webhum'), 'high and twitchy') && str_contains(trail_sight_hint($row(), $at, 'rut'), 'fresh') && str_contains(trail_sight_hint($row(), $at, 'glow'), 'fast'));
q("DELETE FROM landmark_uses WHERE user_id = ? AND landmark_id = ? AND action = 'lair'", [$uid, $lairLm['id']]);
ok('no lair in the region: no line', trail_sight_hint($row(), ['region_id' => -5] + $at, 'snore') === '');
ok('lint: hint=snore / webhum / glow / rut / firstroom are clean, hint=snores is not', !$lint(['rewards' => 'hint=snore,hint=webhum,hint=glow,hint=rut,hint=firstroom'], 'hint=') && (bool)$lint(['rewards' => 'hint=snores'], 'hint='));

echo "== hint=firstroom and the delve-start hook\n";
set_setting('delve_v2', '1'); set_setting('delve_map', '1'); setting('__reload__');
$dLoc = q_one("SELECT l.* FROM locations l JOIN landmarks lm ON lm.location_id = l.id WHERE lm.kind = 'delve' ORDER BY l.id LIMIT 1");
$dLm = landmark_at((int)$dLoc['id']);
require_once $argv[1] . '/includes/delve_v2.php';
$route = dv_route(dv2_seed($uid, (int)$dLm['id']), dv2_slug($dLm), dv_stages((int)$dLm['level']));
$kinds = array_map(fn($n) => $n['kind'], $route['rows'][0]);
q("DELETE FROM trail_sight_tally WHERE user_id = ? AND tkey LIKE 'dvhint#%'", [$uid]);
$h = trail_sight_hint($row(), ['region_id' => (int)$dLoc['region_id'], 'kind' => 'village', 'id' => 0, 'name' => 'x'], 'firstroom');
$want = ['fight' => 'a fight', 'treasure' => 'a treasure room', 'mystery' => 'a mystery room', 'puzzle' => 'a puzzle room'];
ok('the hint names the delve and today\'s first rooms (the run\'s own seed)', str_contains($h, (string)$dLm['name']) && !array_filter($kinds, fn($k) => !str_contains($h, $want[$k] ?? $k)), $h . ' ' . json_encode($kinds));
ok('it leaves a note for the delve start', (int)(trail_sight_tallies($uid)['dvhint#' . $dLm['id']] ?? 0) === sights3a_day_no());
q("DELETE FROM landmark_uses WHERE user_id = ? AND landmark_id = ?", [$uid, $dLm['id']]);
q("UPDATE users SET location_id = ?, energy = 90 WHERE id = ?", [(int)$dLoc['id'], $uid]);
[$dok, $dmsg] = delve_start($row(), (int)$dLm['id']);
$dexp = active_expedition($uid);
ok('the delve starts (v2)', $dok && $dexp && ($dexp['kind'] ?? '') === 'delve', (string)$dmsg);
$dlog = $dexp ? (array)json_decode((string)$dexp['log'], true) : [];
ok('its log says again what the Sight told, from the real route', (bool)array_filter($dlog, fn($l) => str_contains($l, 'Just as the Sight told you') && !array_filter($kinds, fn($k) => !str_contains($l, $want[$k] ?? $k))), json_encode($dlog));
ok('the note is used up', !isset(trail_sight_tallies($uid)['dvhint#' . $dLm['id']]));
q("UPDATE expeditions SET status = 'done' WHERE user_id = ?", [$uid]); dm_scene_purge($uid);
q("DELETE FROM landmark_uses WHERE user_id = ? AND landmark_id = ?", [$uid, $dLm['id']]);
set_setting('delve_v2', '0'); setting('__reload__');
ok('with the v2 delves off: no line', trail_sight_hint($row(), ['region_id' => (int)$dLoc['region_id'], 'kind' => 'village', 'id' => 0, 'name' => 'x'], 'firstroom') === '');

echo "== nxt=: effects on the next Trail stretch\n";
ok('lint: nxt=find / find:2 / calm / quick:30 / skip / peek clean; nxt=fog, quick:90, find:5 refused', !$lint(['rewards' => 'nxt=find,nxt=find:2,nxt=calm,nxt=quick:30,nxt=skip,nxt=peek@50'], 'nxt=') && count($lint(['rewards' => 'nxt=fog,nxt=quick:90,nxt=find:5'], 'nxt=')) === 3);
set_setting('gnav_on', '1'); set_setting('gnav_tiles', '1'); set_setting('game_clock_on', '1'); setting('__reload__');
q("UPDATE expeditions SET status = 'done' WHERE user_id = ?", [$uid]);
q("UPDATE routes SET kind = 'road', steps = 5 WHERE id = 240");
$r = q_one('SELECT * FROM routes WHERE id = 240');
q("UPDATE users SET location_id = ?, level = 30, energy = 90, coins = 500, ev_quickwalk = 0, game_day = 10, game_minute = 360 WHERE id = ?", [$r['a_id'], $uid]);
q('DELETE FROM trail_sight_uses WHERE user_id = ?', [$uid]); q('DELETE FROM trail_pickups WHERE user_id = ?', [$uid]);
[$sok] = start_expedition($row(), 240); ok('the walk starts (5 stretches)', $sok);
$exp = active_expedition($uid); $sc = trail_scene($exp);
$lm = array_values(array_filter($sc['map']['art']['objs'], fn($o) => $o[2] === 'lm-grassland-the-clover-patch'));
$spot = null; foreach ([[-1, 0], [1, 0], [0, -1], [0, 1], [0, 0]] as [$dx, $dy]) if (in_array(tm_tile($sc['map'], $lm[0][0] + $dx, $lm[0][1] + $dy), ['.', ',', 'S'], true)) { $spot = [$lm[0][0] + $dx, $lm[0][1] + $dy]; break; }
$sc['x'] = $spot[0]; $sc['y'] = $spot[1]; trail_save($sc);
trail_sights_ensure_tables();
$put = function (array $chg) use ($base) {
    $r = $chg + $base; q('DELETE FROM trail_sight_rows WHERE slug = ?', [$base['slug']]);
    db_insert('trail_sight_rows', ['slug' => $base['slug'], 'verb' => $r['verb'], 'icon' => $r['icon'], 'energy' => $r['energy'], 'cd' => $r['cd'], 'uses' => $r['uses'], 'cond' => $r['when'], 'chk' => $r['check'], 'rewards' => $r['rewards'], 'win' => $r['win'], 'lose' => $r['lose'], 'tool' => $r['tool'], 'fail_en' => $r['fail_en'], 'active' => 1]);
    q('DELETE FROM trail_sight_uses'); $GLOBALS['gv_sights_reload'] = true; trail_sights_all();
};
$put(['when' => '-', 'energy' => 0, 'uses' => 9, 'check' => '-', 'rewards' => 'buff=grit:1:60,buff2=luck:2:60,nxt=find,nxt=quick:30,nxt=calm,nxt=peek']);
$clear(); q('UPDATE users SET game_minute = 600 WHERE id = ?', [$uid]);
$u = $row(); [$a, $m] = trail_sight_do($u, $exp, $base['slug']); save_exp($exp);
$u = $row(); $exp = active_expedition($uid); $sc = trail_scene($exp);
ok('the Sight with two buffs and nxt= is used', $a, (string)$m);
ok('both lucky moments run', $u['ev_stat'] === 'grit' && $u['ev2_stat'] === 'luck');
ok('the effects wait in the walk state (peek is told at once)', ($sc['st']['nxt'] ?? []) === ['find', 'quick:30', 'calm'], json_encode($sc['st']['nxt'] ?? null));
$log = implode(' | ', (array)json_decode((string)$exp['log'], true));
ok('the log tells them, peek counting the extra find', str_contains($log, 'A find waits on the next stretch') && str_contains($log, '30 game minutes sooner') && (bool)preg_match('/The next stretch has \d+ finds? waiting/', $log), $log);
[, $tk1] = trail_map_make(trail_seed(240, $uid, (int)($sc['st']['sx'] ?? $exp['id']), 1, $sc['st']));
$baseF = count(array_filter($tk1, fn($t) => $t[2] === 'F'));
$sc['st']['phase'] = 'confirm'; trail_save($sc);
$min0 = (int)$row()['game_minute']; $logN = count((array)json_decode((string)$exp['log'], true));
[$nok, $nm] = trail_next($row(), $exp); save_exp($exp);
$sc = trail_scene($exp); $newLog = array_slice((array)json_decode((string)$exp['log'], true), $logN);
ok('on to stretch 2', $nok && (int)$sc['st']['sec'] === 1, (string)$nm);
ok('nxt=find: one more find on it than the map has', count(array_filter($sc['st']['tokens'], fn($t) => $t[2] === 'F')) === $baseF + 1, json_encode($sc['st']['tokens']));
ok('nxt=quick:30: 30 game minutes back', (int)$row()['game_minute'] === $min0 - 30, $min0 . ' -> ' . $row()['game_minute']);
ok('nxt=calm: no surprise at the door (only the told lines)', !array_filter($newLog, fn($l) => !preg_match('/^(🍃 The stretch begins quietly|🗺️ A find waits|⏱️ A quick stretch)/u', $l)) && $exp['encounter'] === null, json_encode($newLog));
ok('used up: nothing pending on the new stretch', empty($sc['st']['nxt']));
$extra = array_values(array_filter($sc['st']['tokens'], fn($t) => $t[2] === 'F'));
$ex = end($extra); ok('the extra find is on floor the gnome can walk to', (bool)tm_path($sc['map'], (int)$sc['map']['entry'][0], (int)$sc['map']['entry'][1], (int)$ex[0], (int)$ex[1]));
$sc = trail_scene($exp); $sc['st']['escort'] = 'Nobody'; trail_save($sc);
ok('nxt=skip is stored', str_contains(sights3a_nxt_add($row(), 'skip'), 'shortcut'));
$sc = trail_scene($exp); [$pok] = trail_prev($row(), $exp); save_exp($exp); $sc = trail_scene($exp);
ok('walking back keeps the pending effect (and the escort)', $pok && ($sc['st']['nxt'] ?? []) === ['skip'] && ($sc['st']['escort'] ?? '') === 'Nobody', json_encode($sc['st']));
[$nok] = trail_next($row(), $exp); save_exp($exp); $sc = trail_scene($exp);
ok('a stretch walked before keeps it for the next new one', $nok && ($sc['st']['nxt'] ?? []) === ['skip'] && ($sc['st']['escort'] ?? '') === 'Nobody', json_encode($sc['st']['nxt'] ?? null));
$sc['st']['phase'] = 'confirm'; trail_save($sc); $min0 = (int)$row()['game_minute'];
[$nok] = trail_next($row(), $exp); save_exp($exp); $sc = trail_scene($exp);
$ex9 = $sc['map']['spots']['9'];
ok('nxt=skip: the next stretch starts at its far end, ready to go on', $nok && (int)$sc['st']['sec'] === 2 && $sc['x'] === (int)$ex9[0] && $sc['y'] === (int)$ex9[1] && $sc['st']['phase'] === 'confirm', json_encode([$sc['x'], $sc['y'], $ex9, $sc['st']['phase']]));
ok('... and its walking time comes back', (int)$row()['game_minute'] === $min0 - gclock_time_cost('travel'), $min0 . ' -> ' . $row()['game_minute']);
ok('the escort walks on into the new stretch', ($sc['st']['escort'] ?? '') === 'Nobody');
$sc['st']['sec'] = 4; trail_save($sc);
ok('on the last stretch: nothing to keep it for', str_contains(sights3a_nxt_add($row(), 'find'), 'No stretch is left') && empty(trail_scene($exp)['st']['nxt']));
q('DELETE FROM trail_sight_rows WHERE slug = ?', [$base['slug']]);
q("UPDATE expeditions SET status = 'done' WHERE user_id = ?", [$uid]); $clear();

echo $fails ? "$fails FAILED\n" : "ok\n";
exit($fails ? 1 : 0);
